"""Actual table UI + actual Web Audio, synchronized from browser timestamps.
Known shoe is an explicitly labelled isolated QA fixture, never production odds evidence.
"""
import os,json,time,base64,subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
out=Path(os.environ.get('BACCARAT_TABLE_PROOF','/workspace/scratch/baccarat-table-proof'));out.mkdir(parents=True,exist_ok=True);frames=out/'frames';frames.mkdir(exist_ok=True);base=os.environ.get('UNITY_URL','http://127.0.0.1:3483')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844},has_touch=True);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.add_init_script('''(()=>{const connect=AudioNode.prototype.connect;AudioNode.prototype.connect=function(target,...rest){if(target instanceof AudioDestinationNode){window.__tableMix??=target.context.createMediaStreamDestination();connect.call(this,__tableMix);}return connect.call(this,target,...rest)}})()''');page.goto(base+'/baccarat/index.html');page.locator('#settings-link').click();page.locator('[data-setting=presentation]').select_option('standard');page.locator('[data-action=back]').click();page.locator('[data-action=tables]').click();page.locator('[data-action="start:lounge"]').click();page.evaluate('''()=>{const s=BACCARAT.session.state,cards=[11,13,1,26,2,9];s.shoe.order=[...cards,...s.shoe.order.filter(c=>!cards.includes(c))];s.shoe.cursor=0;s.shoe.burn=0;}''');page.locator('[data-action="bet:player"]').click();page.screenshot(path=str(out/'betting-390.png'),full_page=True)
 cdp=page.context.new_cdp_session(page);stamps=[]
 def frame(e):
  path=frames/f'{len(stamps):05d}.jpg';path.write_bytes(base64.b64decode(e['data']));stamps.append(e['metadata']['timestamp']);cdp.send('Page.screencastFrameAck',{'sessionId':e['sessionId']})
 cdp.on('Page.screencastFrame',frame);cdp.send('Page.startScreencast',{'format':'jpeg','quality':85,'maxWidth':390,'maxHeight':844,'everyNthFrame':1});start=page.evaluate('''()=>{window.__tableChunks=[];window.__tableRec=new MediaRecorder(__tableMix.stream,{mimeType:'audio/webm;codecs=opus'});__tableRec.ondataavailable=e=>__tableChunks.push(e.data);__tableRec.start();return Date.now()/1000}''');page.wait_for_timeout(350);page.locator('[data-action=confirm]').click();expect(page.locator('[data-action=next]')).to_be_visible(timeout=20000);page.wait_for_timeout(1700);page.screenshot(path=str(out/'result-390.png'),full_page=True);receipt=page.evaluate('()=>BACCARAT.session.state.round.receipt');plan=page.evaluate('()=>BACCARAT.session.state.round.plan');assert len(plan['cards'])==6 and receipt['net']==1000;page.locator('[data-action=next]').click();page.wait_for_timeout(700);cdp.send('Page.stopScreencast');raw=page.evaluate('''async()=>{await new Promise(resolve=>{__tableRec.onstop=resolve;__tableRec.stop()});const bytes=new Uint8Array(await new Blob(__tableChunks).arrayBuffer());let s='';for(const n of bytes)s+=String.fromCharCode(n);return btoa(s)}''');(out/'audio.webm').write_bytes(base64.b64decode(raw));assert not errors,errors;b.close()
lines=[]
for i,t in enumerate(stamps):
 lines.append(f"file '{frames/f'{i:05d}.jpg'}'");lines.append('duration '+str(max(.001,stamps[i+1]-t) if i+1<len(stamps) else .12))
(out/'frames.txt').write_text('\n'.join(lines));offset=start-stamps[0];assert abs(offset)<2,offset
sound=f'adelay={max(0,round(offset*1000))}:all=1' if offset>=0 else f'atrim=start={-offset},asetpts=PTS-STARTPTS'
subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-f','concat','-safe','0','-i',str(out/'frames.txt'),'-i',str(out/'audio.webm'),'-filter:a',sound,'-c:v','libx264','-crf','23','-pix_fmt','yuv420p','-r','30','-c:a','aac','-b:a','128k','-shortest',str(out/'one-round-with-audio.mp4')],check=True)
report={'viewport':[390,844],'fixture':'Known isolated shoe [11,13,1,26,2,9], no production odds claim','cards':len(plan['cards']),'receipt':receipt,'capturedFrames':len(stamps),'audioStartRelativeToFirstFrameSeconds':offset,'errors':errors,'note':'Full DOM screencast and actual WebAudio mix, browser epoch timestamps align tracks. Recording is not performance measurement.'};(out/'proof.json').write_text(json.dumps(report,indent=2));print(json.dumps(report))
